  // i disegni sono sempre uguali: si fanno una volta sola (per ogni prefisso)
  var FATTI = {};
  function una(nome, fn, pDef) { return function (p) { p = p ? p + pDef.slice(3) : pDef; var k = nome + "|" + p; return FATTI[k] || (FATTI[k] = fn(p)); }; }
